package com.madar.files;
import java.util.*;

/** Rebuilds ruled rectangular grids as real Word cells, including rectangular merges. */
final class WordTables {
 static final class Rule {final float x1,y1,x2,y2;Rule(float a,float b,float c,float d){x1=Math.min(a,c);y1=Math.min(b,d);x2=Math.max(a,c);y2=Math.max(b,d);}boolean horizontal(){return y2-y1<1.5f&&x2-x1>8;}boolean vertical(){return x2-x1<1.5f&&y2-y1>8;}}
 static final class Table {float[] xs,ys;int[] parent;List<LayoutWordExporter.Line>[] cells;int cols,rows;
  int root(int i){while(parent[i]!=i){parent[i]=parent[parent[i]];i=parent[i];}return i;}
  void union(int a,int b){parent[root(b)]=root(a);}
  int column(float x){for(int i=0;i<cols;i++)if(x>=xs[i]-1&&x<=xs[i+1]+1)return i;return -1;}
  int row(float y){for(int i=0;i<rows;i++)if(y>=ys[i]-1&&y<=ys[i+1]+1)return i;return -1;}
  boolean add(LayoutWordExporter.Line l){int c=column(l.x+l.w/2),r=row(l.y+l.h/2);if(c<0||r<0)return false;int cell=root(r*cols+c),minR=rows,maxR=-1,minC=cols,maxC=-1;for(int i=0;i<parent.length;i++)if(root(i)==cell){minR=Math.min(minR,i/cols);maxR=Math.max(maxR,i/cols);minC=Math.min(minC,i%cols);maxC=Math.max(maxC,i%cols);}float tolerance=Math.max(2,l.size*.15f);if(l.x<xs[minC]-tolerance||l.x+l.w>xs[maxC+1]+tolerance||l.y<ys[minR]-tolerance||l.y+l.h>ys[maxR+1]+tolerance)return false;cells[cell].add(l);return true;}
  String xml(){StringBuilder s=new StringBuilder("<w:tbl><w:tblPr><w:tblpPr w:horzAnchor=\"page\" w:vertAnchor=\"page\" w:tblpX=\"").append(Math.round(xs[0]*20)).append("\" w:tblpY=\"").append(Math.round(ys[0]*20)).append("\" w:leftFromText=\"0\" w:rightFromText=\"0\" w:topFromText=\"0\" w:bottomFromText=\"0\"/><w:tblW w:type=\"dxa\" w:w=\"").append(Math.round((xs[cols]-xs[0])*20)).append("\"/><w:tblLayout w:type=\"fixed\"/><w:tblCellMar><w:top w:w=\"20\" w:type=\"dxa\"/><w:left w:w=\"20\" w:type=\"dxa\"/><w:bottom w:w=\"20\" w:type=\"dxa\"/><w:right w:w=\"20\" w:type=\"dxa\"/></w:tblCellMar><w:tblBorders>");for(String edge:new String[]{"top","left","bottom","right","insideH","insideV"})s.append("<w:").append(edge).append(" w:val=\"single\" w:sz=\"4\" w:color=\"000000\"/>");s.append("</w:tblBorders></w:tblPr><w:tblGrid>");for(int c=0;c<cols;c++)s.append("<w:gridCol w:w=\"").append(Math.round((xs[c+1]-xs[c])*20)).append("\"/>");s.append("</w:tblGrid>");
   for(int r=0;r<rows;r++){s.append("<w:tr><w:trPr><w:trHeight w:val=\"").append(Math.round((ys[r+1]-ys[r])*20)).append("\" w:hRule=\"atLeast\"/><w:cantSplit/></w:trPr>");for(int c=0;c<cols;){int root=root(r*cols+c),left=c,right=c+1;while(right<cols&&root(r*cols+right)==root)right++;int firstRow=rows,lastRow=-1;for(int i=0;i<parent.length;i++)if(root(i)==root){firstRow=Math.min(firstRow,i/cols);lastRow=Math.max(lastRow,i/cols);}s.append("<w:tc><w:tcPr><w:tcW w:type=\"dxa\" w:w=\"").append(Math.round((xs[right]-xs[left])*20)).append("\"/>");if(right-left>1)s.append("<w:gridSpan w:val=\"").append(right-left).append("\"/>");if(lastRow>firstRow)s.append(r==firstRow?"<w:vMerge w:val=\"restart\"/>":"<w:vMerge/>");s.append("<w:vAlign w:val=\"center\"/></w:tcPr>");List<LayoutWordExporter.Line> lines=cells[root];if(r==firstRow&&!lines.isEmpty()){lines.sort(Comparator.comparingDouble(l->l.y));for(LayoutWordExporter.Line l:lines)s.append(paragraph(l));}else s.append("<w:p/>");s.append("</w:tc>");c=right;}s.append("</w:tr>");}return s.append("</w:tbl>").toString();
  }
 }
 static String paragraph(LayoutWordExporter.Line l){boolean bold=l.font!=null&&l.font.toLowerCase(Locale.ROOT).contains("bold");return "<w:p><w:pPr><w:spacing w:before=\"0\" w:after=\"0\"/>"+(l.rtl?"<w:bidi/><w:jc w:val=\"left\"/>":"")+"</w:pPr><w:r><w:rPr><w:rFonts w:ascii=\"Arial\" w:hAnsi=\"Arial\" w:cs=\"Arial\"/><w:sz w:val=\""+Math.max(10,Math.round(l.size*2))+"\"/><w:szCs w:val=\""+Math.max(10,Math.round(l.size*2))+"\"/>"+(bold?"<w:b/><w:bCs/>":"")+(l.rtl?"<w:rtl/>":"")+"</w:rPr><w:t xml:space=\"preserve\">"+LayoutWordExporter.xml(l.text)+"</w:t></w:r></w:p>";}
 static float[] positions(List<Float> values){Collections.sort(values);List<Float> unique=new ArrayList<>();for(float v:values)if(unique.isEmpty()||v-unique.get(unique.size()-1)>2)unique.add(v);float[] out=new float[unique.size()];for(int i=0;i<out.length;i++)out[i]=unique.get(i);return out;}
 static boolean border(List<Rule> rules,boolean horizontal,float position,float from,float to){List<float[]> spans=new ArrayList<>();for(Rule r:rules)if(horizontal?r.horizontal()&&Math.abs(r.y1-position)<=2:r.vertical()&&Math.abs(r.x1-position)<=2)spans.add(horizontal?new float[]{r.x1,r.x2}:new float[]{r.y1,r.y2});spans.sort(Comparator.comparingDouble(a->a[0]));float end=from;for(float[] span:spans){if(span[0]>end+2)break;if(span[1]>=end)end=Math.max(end,span[1]);}return end>=to-2;}
 static boolean touch(Rule a,Rule b){return a.x1<=b.x2+2&&a.x2+2>=b.x1&&a.y1<=b.y2+2&&a.y2+2>=b.y1;}
 @SuppressWarnings("unchecked") static List<Table> detect(List<Rule> input){List<Rule> rules=new ArrayList<>();for(Rule r:input)if(r.horizontal()||r.vertical())rules.add(r);if(rules.size()>1200)return Collections.emptyList();List<Table> tables=new ArrayList<>();boolean[] seen=new boolean[rules.size()];for(int start=0;start<rules.size();start++){if(seen[start])continue;List<Rule> group=new ArrayList<>();ArrayDeque<Integer> queue=new ArrayDeque<>();queue.add(start);seen[start]=true;while(!queue.isEmpty()){Rule a=rules.get(queue.remove());group.add(a);for(int i=0;i<rules.size();i++)if(!seen[i]&&touch(a,rules.get(i))){seen[i]=true;queue.add(i);}}
   List<Float> x=new ArrayList<>(),y=new ArrayList<>();for(Rule r:group){if(r.vertical())x.add(r.x1);if(r.horizontal())y.add(r.y1);}Table t=new Table();t.xs=positions(x);t.ys=positions(y);t.cols=t.xs.length-1;t.rows=t.ys.length-1;if(t.cols<2||t.cols>40||t.rows<2||t.rows>100)continue;
   if(!border(group,true,t.ys[0],t.xs[0],t.xs[t.cols])||!border(group,true,t.ys[t.rows],t.xs[0],t.xs[t.cols])||!border(group,false,t.xs[0],t.ys[0],t.ys[t.rows])||!border(group,false,t.xs[t.cols],t.ys[0],t.ys[t.rows]))continue;
   t.parent=new int[t.rows*t.cols];t.cells=(List<LayoutWordExporter.Line>[])new List<?>[t.parent.length];for(int i=0;i<t.parent.length;i++){t.parent[i]=i;t.cells[i]=new ArrayList<>();}
   for(int r=0;r<t.rows;r++)for(int c=0;c<t.cols;c++){if(c+1<t.cols&&!border(group,false,t.xs[c+1],t.ys[r],t.ys[r+1]))t.union(r*t.cols+c,r*t.cols+c+1);if(r+1<t.rows&&!border(group,true,t.ys[r+1],t.xs[c],t.xs[c+1]))t.union(r*t.cols+c,(r+1)*t.cols+c);}
   boolean valid=true;int cellCount=0;for(int i=0;i<t.parent.length;i++)if(t.root(i)==i){cellCount++;int minR=t.rows,maxR=-1,minC=t.cols,maxC=-1,count=0;for(int j=0;j<t.parent.length;j++)if(t.root(j)==i){minR=Math.min(minR,j/t.cols);maxR=Math.max(maxR,j/t.cols);minC=Math.min(minC,j%t.cols);maxC=Math.max(maxC,j%t.cols);count++;}if(count!=(maxR-minR+1)*(maxC-minC+1))valid=false;}if(valid&&cellCount>1)tables.add(t);
  }return tables;
 }
}
